from __future__ import annotations

import json
import uuid

try:
    from pydantic_ai.messages import (
        FunctionToolCallEvent,
        FunctionToolResultEvent,
        PartDeltaEvent,
        PartStartEvent,
        RetryPromptPart,
        TextPart,
        TextPartDelta,
        ThinkingPart,
        ThinkingPartDelta,
    )
except ImportError as exc:
    raise ImportError(
        "pydantic-ai-slim is required for Copilot v2. "
        "Install with: pip install rasa-pro[copilot-v2]"
    ) from exc

from rasa.builder.copilot.pydantic_ai import ag_ui_events


def map_tool_result(event: FunctionToolResultEvent) -> list[dict[str, object]]:
    """Map a tool result (success or failure) to TOOL_CALL_RESULT + TOOL_CALL_END."""
    result = event.part
    tool_call_id = event.tool_call_id
    tool_result_message_id = f"tool-result-{tool_call_id}"

    if isinstance(result, RetryPromptPart):
        content = json.dumps({"error": result.model_response()}, separators=(",", ":"))
    else:
        content = result.model_response_str()

    return [
        ag_ui_events.tool_call_result(tool_result_message_id, tool_call_id, content),
        ag_ui_events.tool_call_end(tool_call_id),
    ]


def text_delta_from_event(event: object) -> str | None:
    """Extract a text chunk from a PydanticAI stream event, if present."""
    if isinstance(event, PartStartEvent) and isinstance(event.part, TextPart):
        return event.part.content or None
    if isinstance(event, PartDeltaEvent) and isinstance(event.delta, TextPartDelta):
        return event.delta.content_delta or None
    return None


def _is_thinking_event(event: object) -> bool:
    """Return whether a PydanticAI stream event belongs to a ThinkingPart."""
    if isinstance(event, PartStartEvent) and isinstance(event.part, ThinkingPart):
        return True
    if isinstance(event, PartDeltaEvent) and isinstance(event.delta, ThinkingPartDelta):
        return True
    return False


def _is_text_event(event: object) -> bool:
    """Return whether a PydanticAI stream event carries assistant text."""
    return text_delta_from_event(event) is not None


def _is_tool_event(event: object) -> bool:
    """Return whether an event starts a tool call or delivers a tool result."""
    return isinstance(event, (FunctionToolCallEvent, FunctionToolResultEvent))


class AgUiEventMapper:
    """Translate PydanticAI stream events to AG-UI events.

    Single stateful owner of section bracketing. Both assistant text and
    reasoning are streamed as bracketed sections — opened with a START on the
    first chunk and closed with an END when the section switches or the stream
    finishes. Centralizing both here keeps the two families symmetric and lets
    the orchestrator close every section through one :meth:`close` call,
    including on error, so the frontend never stays stuck mid-section.
    """

    def __init__(self, message_id: str) -> None:
        # Each text section gets its own id: a turn with several assistant text
        # blocks (split by tool calls or reasoning) must stream as separate
        # messages, or the frontend — which keys by ``messageId`` — collapses
        # them into one bubble and drops the interleaved tool calls between them.
        # The run's seed id names the first section; later sections mint their
        # own, mirroring how reasoning sections each get a fresh id.
        self._seed_message_id = message_id
        self._seed_used = False
        self._thinking_id: str | None = None
        self._text_id: str | None = None

    def map(self, event: object) -> list[dict[str, object]]:
        """Map a PydanticAI stream event into zero-or-more AG-UI events.

        Closes the open section only when the incoming event *starts a different*
        section (text <-> reasoning <-> tool), so the two never nest. Benign
        lifecycle events that map to nothing (e.g. ``FinalResultEvent``, which
        pydantic-ai fires mid-stream right after the final message's first
        delta, or part-end markers) must leave the open section untouched —
        otherwise a single assistant message gets torn into two rows (with an
        ugly newline between them) on the frontend.
        """
        prefix: list[dict[str, object]] = []
        if self._thinking_id and (_is_text_event(event) or _is_tool_event(event)):
            prefix += self._close_thinking()
        if self._text_id is not None and (
            _is_thinking_event(event) or _is_tool_event(event)
        ):
            prefix += self._close_text()

        return prefix + self._map_inner(event)

    def close(self) -> list[dict[str, object]]:
        """Flush any still-open text or reasoning section after the stream ends.

        Idempotent: safe to call on both the normal and error exit paths.
        """
        events: list[dict[str, object]] = []
        if self._thinking_id:
            events += self._close_thinking()
        if self._text_id is not None:
            events += self._close_text()
        return events

    def _close_text(self) -> list[dict[str, object]]:
        text_id = self._text_id or ""
        self._text_id = None
        return [ag_ui_events.text_message_end(text_id)]

    def _next_text_id(self) -> str:
        """Return the seed id for the first text section, a fresh id thereafter."""
        if not self._seed_used:
            self._seed_used = True
            return self._seed_message_id
        return f"msg-{uuid.uuid4().hex}"

    def _close_thinking(self) -> list[dict[str, object]]:
        thinking_id = self._thinking_id or ""
        self._thinking_id = None
        return [
            ag_ui_events.reasoning_message_end(thinking_id),
            ag_ui_events.reasoning_end(thinking_id),
        ]

    def _open_thinking(self) -> tuple[str, list[dict[str, object]]]:
        # Close any still-open section first so back-to-back ThinkingParts (e.g.
        # a redacted block followed by a fresh one) can't leak an unbalanced
        # REASONING_START without its matching END.
        events: list[dict[str, object]] = []
        if self._thinking_id:
            events.extend(self._close_thinking())
        thinking_id = f"think-{uuid.uuid4().hex}"
        self._thinking_id = thinking_id
        events.extend(
            [
                ag_ui_events.reasoning_start(thinking_id),
                ag_ui_events.reasoning_message_start(thinking_id),
            ]
        )
        return thinking_id, events

    def _map_inner(self, event: object) -> list[dict[str, object]]:
        delta = text_delta_from_event(event)
        if delta:
            return self._map_text(delta)

        if isinstance(event, PartStartEvent) and isinstance(event.part, ThinkingPart):
            return self._map_thinking_start(event.part)

        if isinstance(event, PartDeltaEvent) and isinstance(
            event.delta, ThinkingPartDelta
        ):
            return self._map_thinking_delta(event.delta)

        if isinstance(event, FunctionToolCallEvent):
            part = event.part
            return [
                ag_ui_events.tool_call_start(part.tool_call_id, part.tool_name),
                ag_ui_events.tool_call_args(part.tool_call_id, part.args_as_json_str()),
            ]

        if isinstance(event, FunctionToolResultEvent):
            return map_tool_result(event)

        return []

    def _map_text(self, delta: str) -> list[dict[str, object]]:
        # Delay TEXT_MESSAGE_START until the first chunk so tool calls or
        # reasoning that precede any assistant text are never nested inside an
        # open text message.
        events: list[dict[str, object]] = []
        if self._text_id is None:
            self._text_id = self._next_text_id()
            events.append(ag_ui_events.text_message_start(self._text_id))
        events.append(ag_ui_events.text_message_content(self._text_id, delta))
        return events

    def _map_thinking_start(self, part: ThinkingPart) -> list[dict[str, object]]:
        thinking_id, mapped = self._open_thinking()
        mapped.extend(
            self._reasoning_payload(thinking_id, part.content, part.signature)
        )
        return mapped

    def _map_thinking_delta(self, delta: ThinkingPartDelta) -> list[dict[str, object]]:
        if self._thinking_id is None:
            thinking_id, mapped = self._open_thinking()
        else:
            thinking_id = self._thinking_id
            mapped = []
        mapped.extend(
            self._reasoning_payload(
                thinking_id, delta.content_delta, delta.signature_delta
            )
        )
        return mapped

    @staticmethod
    def _reasoning_payload(
        thinking_id: str, content: str | None, signature: str | None
    ) -> list[dict[str, object]]:
        """Build the content/signature events shared by thinking start and delta."""
        payload: list[dict[str, object]] = []
        if content:
            payload.append(ag_ui_events.reasoning_message_content(thinking_id, content))
        if signature:
            payload.append(
                ag_ui_events.reasoning_encrypted_value(
                    subtype="message",
                    entity_id=thinking_id,
                    encrypted_value=signature,
                )
            )
        return payload
